<?php
require __DIR__ . '/includes/db.php'; require __DIR__ . '/includes/auth.php'; require __DIR__ . '/includes/navigation.php';
requireLogin(); $user=currentUser(); if(($user['VaiTro']??'')!=='admin'){http_response_code(403);exit('Không có quyền truy cập.');}
$pdo=getDb(); $pdo->exec('CREATE TABLE IF NOT EXISTS PhienBanUngDung(Id INTEGER PRIMARY KEY AUTOINCREMENT,PhienBan TEXT NOT NULL,NgayPhatHanh TEXT NOT NULL,GhiChu TEXT,IsDeleted INTEGER NOT NULL DEFAULT 0)');
if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['delete'])){$pdo->prepare('UPDATE PhienBanUngDung SET IsDeleted=1 WHERE Id=?')->execute([(int)$_POST['delete']]);}else{$data=[$_POST['PhienBan'],$_POST['NgayPhatHanh'],$_POST['GhiChu']??null];if(($id=(int)($_POST['Id']??0))){$data[]=$id;$pdo->prepare('UPDATE PhienBanUngDung SET PhienBan=?,NgayPhatHanh=?,GhiChu=? WHERE Id=?')->execute($data);}else{$pdo->prepare('INSERT INTO PhienBanUngDung(PhienBan,NgayPhatHanh,GhiChu) VALUES(?,?,?)')->execute($data);}}header('Location: /version.php');exit;}
$rows=$pdo->query('SELECT * FROM PhienBanUngDung WHERE COALESCE(IsDeleted,0)=0 ORDER BY NgayPhatHanh DESC,Id DESC')->fetchAll();
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý phiên bản</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="/assets/css/style.css"></head><body><div class="app-shell"><?php renderApplicationSidebar($user,'/about.php'); ?><main class="main-panel"><header class="topbar"><div><h2>Quản lý phiên bản</h2><p>Thêm, sửa hoặc ẩn các mốc phát hành hiển thị tại trang Về ứng dụng.</p></div><a class="btn btn-outline-primary" href="/about.php"><i class="bi bi-info-circle"></i> Về ứng dụng</a></header><section class="card-panel" style="max-width:960px"><form method="post" id="versionForm" class="row g-3"><input name="Id" type="hidden"><div class="col-md-4"><label class="form-label">Phiên bản <span class="text-danger">*</span></label><input name="PhienBan" class="form-control" placeholder="1.0.0" required></div><div class="col-md-4"><label class="form-label">Ngày phát hành <span class="text-danger">*</span></label><input name="NgayPhatHanh" type="date" class="form-control" value="<?=date('Y-m-d')?>" required></div><div class="col-12"><label class="form-label">Ghi chú thay đổi</label><textarea name="GhiChu" class="form-control" rows="3" placeholder="Các thay đổi trong phiên bản..."></textarea></div><div><button class="btn btn-primary"><i class="bi bi-save"></i> Lưu phiên bản</button><button type="button" id="resetVersion" class="btn btn-light">Tạo mới</button></div></form></section><section class="card-panel mt-3" style="max-width:960px"><h5>Lịch sử đã tạo</h5><div class="vstack gap-2 mt-3"><?php foreach($rows as $row):?><article class="border rounded p-3"><div class="d-flex justify-content-between align-items-start gap-3"><div><strong>v<?=htmlspecialchars($row['PhienBan'])?></strong> · <?=date('d/m/Y',strtotime($row['NgayPhatHanh']))?><div class="mt-1"><?=nl2br(htmlspecialchars($row['GhiChu']??''))?></div></div><div class="d-flex gap-2 flex-shrink-0"><button type="button" class="btn btn-sm btn-outline-primary edit-version" data-item='<?=htmlspecialchars(json_encode($row),ENT_QUOTES)?>'><i class="bi bi-pencil"></i></button><form method="post"><button class="btn btn-sm btn-outline-danger" name="delete" value="<?=$row['Id']?>" title="Ẩn phiên bản"><i class="bi bi-eye-slash"></i></button></form></div></div></article><?php endforeach;?><p class="text-muted mb-0 <?= $rows?'d-none':'' ?>">Chưa có phiên bản nào.</p></div></section></main></div><script src="/assets/js/app.js"></script><script>const f=document.getElementById('versionForm');document.querySelectorAll('.edit-version').forEach(b=>b.onclick=()=>{const x=JSON.parse(b.dataset.item);f.Id.value=x.Id;f.PhienBan.value=x.PhienBan;f.NgayPhatHanh.value=x.NgayPhatHanh;f.GhiChu.value=x.GhiChu||'';scrollTo({top:0,behavior:'smooth'})});document.getElementById('resetVersion').onclick=()=>{f.reset();f.Id.value=''};</script></body></html>
